1	export type Cell = [number, number];
2	
3	const cellKey = ([x, y]: Cell): string => `${x},${y}`;
4	
5	const neighbors = ([x, y]: Cell): Cell[] => [
6	  [x - 1, y - 1],
7	  [x, y - 1],
8	  [x + 1, y - 1],
9	  [x - 1, y],
10	  [x + 1, y],
11	  [x - 1, y + 1],
12	  [x, y + 1],
13	  [x + 1, y + 1],
14	];
15	
16	
17	const isAliveNextGeneration = (isAlive: boolean, liveNeighbors: number): boolean =>
18	  isAlive ? liveNeighbors === 2 || liveNeighbors === 3 : liveNeighbors === 3;
19	
20	export const nextGeneration = (liveCells: Cell[]): Cell[] => {
21	  const livingKeys = new Set(liveCells.map(cellKey));
22	  const isAlive = (cell: Cell): boolean => livingKeys.has(cellKey(cell));
23	  const liveNeighborCount = (cell: Cell): number =>
24	    neighbors(cell).filter(isAlive).length;
25	
26	  const candidates = new Map(
27	    liveCells
28	      .flatMap((cell) => [cell, ...neighbors(cell)])
29	      .map((cell) => [cellKey(cell), cell] as const),
30	  );
31	
32	  return [...candidates.values()].filter((cell) =>
33	    isAliveNextGeneration(isAlive(cell), liveNeighborCount(cell)),
34	  );
35	};
